%[text] # Mass-spring example
%[text] Worked example of the clamped beam found in [Evaluating applied force reduced-order models: verification](https://doi.org/10.1007/s11071-026-12899-6)
%[text] ![](text:image:9a57)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number, the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\mass_spring"
set_logging_level(3)
set_visualisation_level(3)
%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\cubic\_mass\_spring\\cubic\_mass\_spring.m](file:.\\geometry\\cubic_mass_spring\\cubic_mass_spring.m)), ROM limit and reduction basis needs to be specified.
%--------- System Settings ---------%
system_name = "cubic_mass_spring";
energy_limit = 0.04; %(J)
reduction_basis = 1;
%-----------------------------------%

%--------- Calibration Settings ---------%
Calibration_Opts.calibration_scale_factor = 1;
%----------------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.solver_algorithm = "riks";
Static_Opts.max_parallel_jobs = 1;
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"calibration_opts",Calibration_Opts,"static_opts",Static_Opts);
Static_Data = Static_Dataset(Model);
Static_Data.save_data;
%%
%[text] ### Periodic orbits 
rom_name = "cubic_mass_spring_1";
Dyn_Data = initalise_dynamic_data(rom_name);
Dyn_Data = Dyn_Data.remove_solution("all");
%[text] 
Additional_Output.output = "physical displacement";
Additional_Output.type = "max";
Additional_Output.dof = 1;
Dyn_Data = Dyn_Data.add_additional_output(Additional_Output);
%[text] 
%[text] ICE-IC ROM
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 2e-1;
Continuation_Opts.min_inc = 1e-2;
Continuation_Opts.forward_steps = 500;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.energy_limit_multiplier = 2;
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"type","rom","opts",Continuation_Opts);
%[text] 
%[text] ICE ROM
Continuation_Opts.inertial_compensation = 0;
Dyn_Data = Dyn_Data.add_backbone(1,"type","rom","opts",Continuation_Opts);
%[text] 
%[text] FOM
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e0;
Continuation_Opts.max_inc = 1e0;
Continuation_Opts.min_inc = 1e0;
Continuation_Opts.energy_limit_multiplier = 20;
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"type","fom","opts",Continuation_Opts);

%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 1e-1;
Continuation_Opts.max_inc = 2e-1;
Continuation_Opts.min_inc = 1e-2;
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"type","fom","opts",Continuation_Opts);

%--------- Continuation Settings ---------%
Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 200;
Continuation_Opts.collocation_degree = 6;
%-----------------------------------------%
Dyn_Data = Dyn_Data.restart_point(3,5,"po","opts",Continuation_Opts);
%[text] 
%[text] Plot all together
compare_solutions("physical amplitude","cubic_mass_spring_1",[4,5],"cubic_mass_spring_1",1,"cubic_mass_spring_1",2)

